selector_to_html = {"a[href=\"#pyskyfire-thermo-fluid-fluid\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.thermo.fluid.Fluid<a class=\"headerlink\" href=\"#pyskyfire-thermo-fluid-fluid\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.thermo.fluid.Fluid\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.fluid.Fluid\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.fluid.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Fluid</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">type</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">propellants</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fractions</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">basis</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'mass'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">precision</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">3</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Mixture helper for fluids.</p><p>Stores a set of component names and composition.</p><p class=\"rubric\">Notes</p><p>Fractions are re-normalized internally when converting to mole basis to\nguard against small rounding errors.</p></dd>", "a[href=\"#pyskyfire.thermo.fluid.Fluid.as_mole_fractions\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.fluid.Fluid.as_mole_fractions\">\n<span class=\"sig-name descname\"><span class=\"pre\">as_mole_fractions</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd><p>Convert the stored composition to mole fractions.</p><p class=\"rubric\">Notes</p><p>For a mass-basis input, the conversion uses\n<span class=\"math notranslate nohighlight\">\\(x_i = \\frac{w_i/M_i}{\\sum_j w_j/M_j}\\)</span> with molar masses\n<span class=\"math notranslate nohighlight\">\\(M_i\\)</span> from <a class=\"reference internal\" href=\"#pyskyfire.thermo.fluid.Fluid.molar_masses\" title=\"pyskyfire.thermo.fluid.Fluid.molar_masses\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">molar_masses()</span></code></a>.</p></dd>", "a[href=\"#pyskyfire.thermo.fluid.Fluid.coolprop_string\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.fluid.Fluid.coolprop_string\">\n<span class=\"sig-name descname\"><span class=\"pre\">coolprop_string</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd><p>Format a CoolProp HEOS mixture string.</p><p class=\"rubric\">Notes</p><p>The composition is always exported on a <strong>mole</strong> basis, using\n<a class=\"reference internal\" href=\"#pyskyfire.thermo.fluid.Fluid.as_mole_fractions\" title=\"pyskyfire.thermo.fluid.Fluid.as_mole_fractions\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">as_mole_fractions()</span></code></a> for conversion when needed.</p></dd>", "a[href=\"#pyskyfire.thermo.fluid.Fluid.molar_masses\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.fluid.Fluid.molar_masses\">\n<span class=\"sig-name descname\"><span class=\"pre\">molar_masses</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd><p>Return molar masses for each component.</p><p class=\"rubric\">Notes</p><p>Values are retrieved via <code class=\"docutils literal notranslate\"><span class=\"pre\">CoolProp.PropsSI(\"M\",</span> <span class=\"pre\">name)</span></code>.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
